            msg = %{msg | messageC2STimestamp: value}
            parse_key_value(rest, msg)

          <<"*", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | participant: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<" ", 0::1, varint_value::7, rest::binary>> ->
            value = WAWebProtobufsWeb.WebMessageInfo.Status.decode(varint_value)
            msg = %{msg | status: value}
            parse_key_value(rest, msg)

          <<" ", bytes::binary>> ->
            {value, rest} =
              Protox.Decode.parse_enum(bytes, WAWebProtobufsWeb.WebMessageInfo.Status)

            msg = %{msg | status: value}
            parse_key_value(rest, msg)

          <<"\x18", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | messageTimestamp: value}
            parse_key_value(rest, msg)

          <<"\x18", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_uint64(bytes)
            msg = %{msg | messageTimestamp: value}
            parse_key_value(rest, msg)

          <<"\x12", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | message:
                  case :erlang.map_get(:message, msg) do
                    nil ->
                      WAWebProtobufsE2E.Message.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.Message.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"\n", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | key:
                  case :erlang.map_get(:key, msg) do
                    nil ->
                      WACommon.MessageKey.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WACommon.MessageKey.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<bytes::binary>> ->
            {tag, wire_type, rest} = Protox.Decode.parse_key(bytes)
            {value, rest} = Protox.Decode.parse_unknown(tag, wire_type, rest)
            msg = %{msg | __uf__: [value | :erlang.map_get(:__uf__, msg)]}
            parse_key_value(rest, msg)
        end
      end
    )
  )

  (
    @spec unknown_fields(struct()) :: [{non_neg_integer(), Protox.Types.tag(), binary()}]
    def unknown_fields(msg), do: msg.__uf__

    @spec unknown_fields_name() :: :__uf__
    def unknown_fields_name(), do: :__uf__

    @spec clear_unknown_fields(struct) :: struct
    def clear_unknown_fields(msg), do: struct!(msg, __uf__: [])
  )

  (
    @spec default(atom()) ::
            {:ok, Protox.Scalar.scalar_default_value_type()}
            | {:error, :no_such_field | :no_default_value}
    def default(field_name), do: Protox.MessageSchema.default(@schema, field_name)
  )
end
